using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type"
        // Fix: Preserve old property name for existing documents
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|Key" to just "Key"
        // Fix: Preserve old id format for existing documents
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasValueGenerator<LegacyIdValueGenerator>();

        // Breaking change 3: HasIndex is not supported on Cosmos DB (now throws instead of being ignored)
        // Fix: Removed the unsupported .HasIndex() call

        // Breaking change 4: Sync I/O now throws by default
        // Fix: See SyncJob.cs — changed to async, or opt-in below:
        // optionsBuilder.UseCosmos(...).EnableSyncExecution();
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

// Value generator to preserve the legacy "Discriminator|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

